KG42.register("rules-6c78f6f979dfe5192b8dac50",{"id":"25-p2p_ancillary_bidding::v141-c-R014","paper":"25-p2p_ancillary_bidding","record":{"rule_id":"v141-c-R014","mechanism_id":"v141-a-M03-ancillary-service","name":"Local market clearing","process_stage":"clearing","market_meaning":"The utility, acting as coordinator of the community's ancillary-service procurement, determines which bids are accepted and the quantities procured. Scope: The utility's coordination of ancillary-service procurement from customers in the P2P energy trading community during the ancillary-service Agreement Period. Condition: After collecting customers' ancillary-service bids. Procurement quotas should initially distribute the requested service equally among submitting customers; quotas exceeding customers' bids are redistributed to customers needing additional quotas. Scope: Ancillary-service quota allocation among submitting customers in the P2P energy trading community, separately for each target time slot. Condition: After collecting ancillary-service bids, during quota distribution. Set the customer's final procurement quota equal to its submitted ancillary-service bid. Scope: Step III of ancillary-service procurement allocation, for each submitting customer and target time slot. Condition: The customer's distributed quota is at least its submitted ancillary-service bid. The customer chooses its final procurement quota between zero and its distributed quota, inclusive. Scope: Step III of ancillary-service procurement allocation, for each submitting customer and target time slot. Condition: The customer's distributed quota is below its submitted ancillary-service bid.","independence_rationale":"Relations governed by the approved function clearing.local under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["clearing.local","coordination.local_operator"],"E":[{"edge_id":"v141-c-R014-E001","source":"coordination.local_operator","target":"clearing.local","type":"links","constraint_ids":["v141-c-R014-C001"],"evidence_ids":["v141-b-g02-E09-as-step1-publication","v141-b-g02-E11-as-step3-fairness"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Ancillary-service quota allocation among submitting customers in the P2P energy trading community, separately for each target time slot. | Step III of ancillary-service procurement allocation, for each submitting customer and target time slot. | The utility's coordination of ancillary-service procurement from customers in the P2P energy trading community during the ancillary-service Agreement Period.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-E09-as-step1-publication","v141-b-g02-E11-as-step3-fairness","v141-b-g02-E12-fig3-quota-algorithm"]},"x":[{"variable_id":"v141-c-R014-v-q","symbol":"q_{i,t}","meaning":"Amount of ancillary service to be procured from customer i for target time slot t (the quota), initialized and updated by the Fig. 3 quota-allocation algorithm; after Step III it is the final procurement quota.","kind":"operational","domain":"kW; quota amount for customer i in submitting set I* and target time slot t, initialized at 0 and updated by nonnegative surplus allocation in the clearing procedure","unit":"kW","indices":["i","t"],"evidence_ids":["v141-b-g02-E12-fig3-quota-algorithm"]},{"variable_id":"v141-c-R014-v-Q","symbol":"Q_t","meaning":"Sum of surplus quotas of all customers for target time slot t in the current iteration of the quota-allocation algorithm.","kind":"operational","domain":"kW; initialized to D_t^{AS} and recomputed by Eq. (22) in the clearing procedure","unit":"kW","indices":["t"],"evidence_ids":["v141-b-g02-E12-fig3-quota-algorithm"]},{"variable_id":"v141-c-R014-v-Istarstar","symbol":"I^{**}","meaning":"Set of submitting customers whose current quota is lower than their submitted bid and therefore need additional quota.","kind":"operational","domain":"Subset of I* satisfying q_{i,t}-b_{i,t}^{AS}\u003c0 at the current iteration for target time slot t.","unit":null,"indices":["t"],"evidence_ids":["v141-b-g02-E12-fig3-quota-algorithm"]}],"theta":[{"parameter_id":"v141-c-R014-p-b","symbol":"b_{i,t}^{AS}","meaning":"Magnitude of the ancillary-service bid submitted by customer i for target time slot t; used as an input to the quota-allocation procedure.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"kW","indices":["i","t"],"evidence_ids":["v141-b-g02-E10-as-step2-bid-form-eq17","v141-b-g02-E12-fig3-quota-algorithm"]},{"parameter_id":"v141-c-R014-p-D","symbol":"D_t^{AS}","meaning":"Total magnitude of ancillary service required for target time slot t, published by the power utility; used to initialize the total surplus quota Q_t.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"kW","indices":["t"],"evidence_ids":["v141-b-g02-E09-as-step1-publication","v141-b-g02-E12-fig3-quota-algorithm"]},{"parameter_id":"v141-c-R014-p-Istar","symbol":"I^*","meaning":"Set of customers who submit ancillary-service bids.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-E10-as-step2-bid-form-eq17","v141-b-g02-E12-fig3-quota-algorithm"]},{"parameter_id":"v141-c-R014-p-T","symbol":"T","meaning":"Set of time slots within the Target Time Period T for which the ancillary-service procurement allocation is performed.","value":{"kind":"symbolic","number_value":null,"text_value":"Target Time Period T"},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-E09-as-step1-publication","v141-b-g02-E12-fig3-quota-algorithm"]}],"phi":[{"constraint_id":"v141-c-R014-C001","kind":"procedural","role":"core","statement":"The utility, acting as coordinator of the community's ancillary-service procurement, determines which bids are accepted and the quantities procured. Scope: The utility's coordination of ancillary-service procurement from customers in the P2P energy trading community during the ancillary-service Agreement Period. Condition: After collecting customers' ancillary-service bids.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator","clearing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-E09-as-step1-publication","v141-b-g02-E11-as-step3-fairness"]},{"constraint_id":"v141-c-R014-C002","kind":"procedural","role":"core","statement":"Procurement quotas should initially distribute the requested service equally among submitting customers; quotas exceeding customers' bids are redistributed to customers needing additional quotas. Scope: Ancillary-service quota allocation among submitting customers in the P2P energy trading community, separately for each target time slot. Condition: After collecting ancillary-service bids, during quota distribution.","expression":"q_{i,t}\\leftarrow 0\\quad \\forall i\\in I^*;\\qquad Q_t\\leftarrow D_t^{AS};\\qquad \\text{repeat } I^{**}={i\\in I^*\\mid q_{i,t}-b_{i,t}^{AS}\u003c0};\\quad q_{i,t}\\leftarrow q_{i,t}+\\frac{Q_t}{|I^{**}|}\\ \\forall i\\in I^{**};\\quad Q_t\\leftarrow\\sum_{i\\in I^*}\\max(q_{i,t}-b_{i,t}^{AS},0)\\ \\text{until }Q_t=0\\text{ or }I^{**}=\\varnothing.","formalization_origin":"source","template_id":null,"members":["clearing.local"],"variable_refs":["v141-c-R014-v-q","v141-c-R014-v-Q","v141-c-R014-v-Istarstar"],"parameter_refs":["v141-c-R014-p-b","v141-c-R014-p-D","v141-c-R014-p-Istar","v141-c-R014-p-T"],"evidence_ids":["v141-b-g02-E11-as-step3-fairness","v141-b-g02-E12-fig3-quota-algorithm","v141-b-g02-E09-as-step1-publication"]},{"constraint_id":"v141-c-R014-C003","kind":"procedural","role":"core","statement":"Set the customer's final procurement quota equal to its submitted ancillary-service bid. Scope: Step III of ancillary-service procurement allocation, for each submitting customer and target time slot. Condition: The customer's distributed quota is at least its submitted ancillary-service bid.","expression":"q_{i,t}=b_{i,t}^{AS}\\quad\\text{if }q_{i,t}\\ge b_{i,t}^{AS},\\ \\forall i\\in I^*,\\ t\\in T.","formalization_origin":"source","template_id":null,"members":["clearing.local"],"variable_refs":["v141-c-R014-v-q"],"parameter_refs":["v141-c-R014-p-b","v141-c-R014-p-Istar","v141-c-R014-p-T"],"evidence_ids":["v141-b-g02-E12-fig3-quota-algorithm"]},{"constraint_id":"v141-c-R014-C004","kind":"procedural","role":"core","statement":"The customer chooses its final procurement quota between zero and its distributed quota, inclusive. Scope: Step III of ancillary-service procurement allocation, for each submitting customer and target time slot. Condition: The customer's distributed quota is below its submitted ancillary-service bid.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["clearing.local"],"variable_refs":["v141-c-R014-v-q"],"parameter_refs":["v141-c-R014-p-b","v141-c-R014-p-Istar","v141-c-R014-p-T"],"evidence_ids":["v141-b-g02-E12-fig3-quota-algorithm"]},{"constraint_id":"v141-c-R014-C005","kind":"mathematical","role":"supporting","statement":"For each target time slot, initialize the ancillary-service procurement quota of every submitting customer to zero.","expression":"q_{i,t}=0\\quad \\forall i\\in I^*\\quad\\text{(for each }t\\in T\\text{)}","formalization_origin":"source","template_id":null,"members":["clearing.local"],"variable_refs":["v141-c-R014-v-q"],"parameter_refs":["v141-c-R014-p-Istar","v141-c-R014-p-T"],"evidence_ids":["v141-b-g02-E12-fig3-quota-algorithm"]},{"constraint_id":"v141-c-R014-C006","kind":"mathematical","role":"supporting","statement":"Initialize the sum of surplus quotas for the target time slot to the total ancillary-service demand.","expression":"Q_t=D_t^{AS}","formalization_origin":"source","template_id":null,"members":["clearing.local"],"variable_refs":["v141-c-R014-v-Q"],"parameter_refs":["v141-c-R014-p-D"],"evidence_ids":["v141-b-g02-E12-fig3-quota-algorithm","v141-b-g02-E09-as-step1-publication"]},{"constraint_id":"v141-c-R014-C007","kind":"mathematical","role":"supporting","statement":"Generate the set of submitting customers whose current quotas are lower than their submitted bids.","expression":"I^{**}={i\\in I^*\\mid q_{i,t}-b_{i,t}^{AS}\u003c0}","formalization_origin":"source","template_id":null,"members":["clearing.local"],"variable_refs":["v141-c-R014-v-q","v141-c-R014-v-Istarstar"],"parameter_refs":["v141-c-R014-p-b","v141-c-R014-p-Istar"],"evidence_ids":["v141-b-g02-E12-fig3-quota-algorithm"]},{"constraint_id":"v141-c-R014-C008","kind":"mathematical","role":"supporting","statement":"Distribute the total surplus quota equally among the customers who need more quota.","expression":"q_{i,t}=q_{i,t}+\\frac{Q_t}{|I^{**}|}\\quad \\forall i\\in I^{**}","formalization_origin":"source","template_id":null,"members":["clearing.local"],"variable_refs":["v141-c-R014-v-q","v141-c-R014-v-Q","v141-c-R014-v-Istarstar"],"parameter_refs":[],"evidence_ids":["v141-b-g02-E12-fig3-quota-algorithm"]},{"constraint_id":"v141-c-R014-C009","kind":"mathematical","role":"supporting","statement":"Calculate the total surplus quota as the sum over submitting customers of the positive excess of current quota over submitted bid.","expression":"Q_t=\\sum_{i\\in I^*}\\max(q_{i,t}-b_{i,t}^{AS},0)","formalization_origin":"source","template_id":null,"members":["clearing.local"],"variable_refs":["v141-c-R014-v-q","v141-c-R014-v-Q"],"parameter_refs":["v141-c-R014-p-b","v141-c-R014-p-Istar"],"evidence_ids":["v141-b-g02-E12-fig3-quota-algorithm"]},{"constraint_id":"v141-c-R014-C010","kind":"procedural","role":"supporting","statement":"If the surplus quota is nonzero and the set of quota-needing customers is nonempty, return to Step I; otherwise continue to Step III.","expression":"\\text{if }Q_t\\ne0\\text{ and }I^{**}\\ne\\varnothing\\text{ then repeat Step I; otherwise continue to Step III}","formalization_origin":"source","template_id":null,"members":["clearing.local"],"variable_refs":["v141-c-R014-v-Q","v141-c-R014-v-Istarstar"],"parameter_refs":[],"evidence_ids":["v141-b-g02-E12-fig3-quota-algorithm"]}],"pi":[{"evidence_id":"v141-b-g02-E09-as-step1-publication","location":{"location_id":"src-212077b9a1-p06-c1r2__v141-a-M03-bidding","page":6,"printed_page":null,"section":null,"anchor_text":"of the net load of a customer as a whole, rather than the change of power output/consumption of spec","equation_id":"(15)-(16)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"As the first step, based on the assessment of the future operational status of power systems, the power utility will broadcast the total demand and prices of ancillary services to all the customers in the P2P energy trading community: \\(D^{AS}=\\{D_t^{AS}\\,|\\,t\\in T\\}\\), (15) \\(p^{AS}=\\{p_t^{AS}\\,|\\,t\\in T\\}\\), (16) where \\(D^{AS}\\) is the set of the magnitude (kW) of the ancillary services required for the time slots within the Target Time Period T, and \\(p^{AS}\\) is the set of prices (£/kW/h) that the power utility is willing to pay for the ancillary services provided by the customers. The power utility will also specify the type of ancillary services needed (either 'Type-1 AS' or 'Type-2 AS'). Note that how the power utility decides \\(D^{AS}\\) and \\(p^{AS}\\) involves comprehensive analysis of the power systems managed by the power utility, which is out of the scope of this paper."},{"evidence_id":"v141-b-g02-E11-as-step3-fairness","location":{"location_id":"src-212077b9a1-p06-c2r1__v141-a-M03-clearing","page":6,"printed_page":null,"section":null,"anchor_text":"Applied Energy 278 (2020) 115671 ng After collecting the bids from the customers in the P2P energy a","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"After collecting the bids from the customers in the P2P energy trading community (a time window can be defined in the Agreement Period for this purpose), the power utility needs to decide which of and to what extent the bids are to be accepted/declined. To achieve the fairness, the power utility in principle should distribute the amount of services to be procured averagely on the customers who have submitted the bids. However, the amount of services to be procured from each customer (called as the 'quota') calculated in this way may be higher than some customers' bids, and thus the surplus quotas can be given to other customers in need. With the above considerations, the process detailed in Fig. 3 is proposed for the power utility to decide the amount of services to be procured from the customers."},{"evidence_id":"v141-b-g02-E12-fig3-quota-algorithm","location":{"location_id":"src-212077b9a1-p06-c2r4__v141-a-M03-clearing","page":6,"printed_page":null,"section":null,"anchor_text":"7) he at he d. he e­ Fig. 3. Distribution of the ancillary service procurement among customers. 6","equation_id":"(18)-(22)","figure_id":"Fig. 3","table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"Distribution of the ancillary service procurement among customers (for each time slot t in the Target Time Period T)\nInitialization:\nInitialize the amount of ancillary service to be procured from each customer (i.e. the 'quota'), \\(q_{i,t}\\), by \\(q_{i,t}=0\\quad \\forall i\\in I^*\\), (18) and initialize the sum of the surplus quotas of all customers, \\(Q_t=D_t^{AS}\\). (19)\nStep I:\nFirst generate the set of customers whose quotas are lower than their bids by \\(I^{**}=\\{i\\in I^*\\,|\\,q_{i,t}-b_{i,t}^{AS}\u003c0\\}\\). (20)\nThen distribute the total surplus quota averagely on the customers who need more quotas by \\(q_{i,t}=q_{i,t}+\\frac{Q_t}{|I^{**}|}\\quad \\forall i\\in I^{**}\\). (21)\nStep II:\nCalculate the total surplus quota by \\(Q_t=\\sum_{i\\in I^*}(\\max(q_{i,t}-b_{i,t}^{AS},0))\\). (22)\nIf \\(Q_t\\ne 0\\) and \\(I^{**}\\ne \\varnothing\\), go back to Step I. Otherwise, continue to Step III.\nStep III:\nDecide the amount of ancillary service to be procured from each customer according to the following logic (presented as pseudo-codes):\n1. if \\(q_{i,t}\\ge b_{i,t}^{AS}\\)\n2. \\(q_{i,t}=b_{i,t}^{AS}\\)\n3. else\n4. the customer i chooses a value from \\([0,q_{i,t}]\\) as the final \\(q_{i,t}\\)\n5. end if"},{"evidence_id":"v141-b-g02-E10-as-step2-bid-form-eq17","location":{"location_id":"src-212077b9a1-p06-c1r3__v141-a-M03-bidding","page":6,"printed_page":null,"section":null,"anchor_text":"D = Dt |t ∈T , (15) tr { } arpAS = pASt |t ∈T , (16) where DAS is the set of the magnitude (kW) of t","equation_id":"(17)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"After receiving the demand and prices of ancillary services required by the power utility as described in Step 1, the customers will run optimization and submit their bids to the power utility. A bid is in the form of \\(B_i^{AS}=\\{b_{i,t}^{AS}\\,|\\,t\\in T\\}\\quad \\forall i\\in I^*\\subseteq I,\\) (17) where \\(B_i^{AS}\\) is the bid of customer i for providing ancillary services for the Target Time Period T, and \\(b_{i,t}^{AS}\\) is the magnitude (kW) of the service that the customer would like to provide for the time slot t. \\(I^*\\) is the set of the customers who submit the bids. Note that the bids only include the amount of services to be provided. In the design of this paper, the prices of the services are fixed by the utility as published in Step 1."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M03-bidding","v141-a-M03-clearing","v141-a-M03-participation","v141-a-M03-pricing"],"extras":{"decision_anchor":"clearing.local","graph_fact_supports":[[{"evidence_id":"v141-b-g02-E11-as-step3-fairness","quote":"After collecting the bids from the customers in the P2P energy trading community (a time window can be defined in the Agreement Period for this purpose), the power utility needs to decide which of and to what extent the bids are to be accepted/declined."},{"evidence_id":"v141-b-g02-E09-as-step1-publication","quote":"As the first step, based on the assessment of the future operational status of power systems, the power utility will broadcast the total demand and prices of ancillary services to all the customers in the P2P energy trading community:"}],[{"evidence_id":"v141-b-g02-E11-as-step3-fairness","quote":"To achieve the fairness, the power utility in principle should distribute the amount of services to be procured averagely on the customers who have submitted the bids. However, the amount of services to be procured from each customer (called as the 'quota') calculated in this way may be higher than some customers' bids, and thus the surplus quotas can be given to other customers in need."}],[{"evidence_id":"v141-b-g02-E12-fig3-quota-algorithm","quote":"Step III:\nDecide the amount of ancillary service to be procured from each customer according to the following logic (presented as pseudo-codes):\n1. if \\(q_{i,t}\\ge b_{i,t}^{AS}\\)\n2. \\(q_{i,t}=b_{i,t}^{AS}\\)"}],[{"evidence_id":"v141-b-g02-E12-fig3-quota-algorithm","quote":"1. if \\(q_{i,t}\\ge b_{i,t}^{AS}\\)\n2. \\(q_{i,t}=b_{i,t}^{AS}\\)\n3. else\n4. the customer i chooses a value from \\([0,q_{i,t}]\\) as the final \\(q_{i,t}\\)\n5. end if"}]],"C2_formalization":{"graph_sha256":"90aeb5abd88ffa77cc2af650d2394c5ccd23b4bee98073fbaa8b8bc51569b2f3","applicability":"formalized","reason":"The quota-allocation procedure is supported by the unreviewed candidate B transcription of Fig. 3: Eqs. (18)-(22) and the Step III pseudo-code. Equations (18)-(22) are formalized faithfully against the clearing.local node and its existing coordination edge E001. The Step III cap branch is formalized. The Step III customer-choice branch remains not_formalized because the source pseudo-code reassigns q_{i,t} in place and does not define distinct pre-choice and final quota symbols; introducing such symbols would invent notation. Evidence remains unreviewed candidate support, not independently audited source verification.","bindings":[{"object_id":"v141-c-R014-v-q","node_ids":["clearing.local"],"edge_ids":["v141-c-R014-E001"],"rationale":"q_{i,t} is the quota determined in local clearing by the utility-coordinated allocation procedure; edge E001 links the coordinating utility to clearing.local."},{"object_id":"v141-c-R014-v-Q","node_ids":["clearing.local"],"edge_ids":["v141-c-R014-E001"],"rationale":"Q_t is a clearing-state quantity maintained inside the quota-allocation iteration under the utility-coordinated clearing relation."},{"object_id":"v141-c-R014-v-Istarstar","node_ids":["clearing.local"],"edge_ids":["v141-c-R014-E001"],"rationale":"I^{**} is generated during the clearing allocation procedure to select submitting customers needing additional quota."},{"object_id":"v141-c-R014-p-b","node_ids":["clearing.local"],"edge_ids":["v141-c-R014-E001"],"rationale":"b_{i,t}^{AS} is a submitted bid magnitude used as an input parameter in the clearing quota equations; it is bound to clearing.local as an input to the utility-coordinated allocation."},{"object_id":"v141-c-R014-p-D","node_ids":["coordination.local_operator","clearing.local"],"edge_ids":["v141-c-R014-E001"],"rationale":"D_t^{AS} is published by the coordinating utility and initializes total surplus quota Q_t in clearing.local; edge E001 is exactly the coordination-to-clearing link."},{"object_id":"v141-c-R014-p-Istar","node_ids":["clearing.local"],"edge_ids":["v141-c-R014-E001"],"rationale":"I* is the set of bidding customers over which the clearing algorithm aggregates quotas and bids."},{"object_id":"v141-c-R014-p-T","node_ids":["clearing.local"],"edge_ids":[],"rationale":"T is the target-period time-slot index set for the clearing allocation procedure; no rule-specific edge is required beyond clearing.local."},{"object_id":"v141-c-R014-C002","node_ids":["clearing.local"],"edge_ids":["v141-c-R014-E001"],"rationale":"C002 is the quota-allocation procedure, here transcribed from the Fig. 3 iterative equations; edge E001 identifies the utility-coordinated clearing relation."},{"object_id":"v141-c-R014-C003","node_ids":["clearing.local"],"edge_ids":["v141-c-R014-E001"],"rationale":"C003 is the Step III quota-cap branch of the clearing procedure under the utility-coordinated allocation."},{"object_id":"v141-c-R014-C005","node_ids":["clearing.local"],"edge_ids":["v141-c-R014-E001"],"rationale":"C005 formalizes initialization of quotas inside clearing.local under edge E001."},{"object_id":"v141-c-R014-C006","node_ids":["clearing.local"],"edge_ids":["v141-c-R014-E001"],"rationale":"C006 formalizes initialization of the surplus-quota state inside the clearing procedure."},{"object_id":"v141-c-R014-C007","node_ids":["clearing.local"],"edge_ids":["v141-c-R014-E001"],"rationale":"C007 formalizes the set of quota-needing customers generated during clearing."},{"object_id":"v141-c-R014-C008","node_ids":["clearing.local"],"edge_ids":["v141-c-R014-E001"],"rationale":"C008 formalizes the equal redistribution step inside the clearing procedure."},{"object_id":"v141-c-R014-C009","node_ids":["clearing.local"],"edge_ids":["v141-c-R014-E001"],"rationale":"C009 formalizes recalculation of surplus quota inside the clearing procedure."},{"object_id":"v141-c-R014-C010","node_ids":["clearing.local"],"edge_ids":["v141-c-R014-E001"],"rationale":"C010 formalizes the iteration-control condition of the clearing allocation algorithm."}],"revision_requests":[]}},"quarantined_references":[]}});
